pub fn trace_lasips2_reg_read(_size: std::ffi::c_uint, _id: std::ffi::c_int, _addr: u64, _name: &std::ffi::CStr, _val: u64)
{
    if trace_event_state_is_enabled(unsafe { _TRACE_LASIPS2_REG_READ_DSTATE}) {
        let format_string = c"lasips2_reg_read %u %d addr 0x%llx%s -> 0x%llx\n";
        if (unsafe { bindings::qemu_loglevel } & bindings::LOG_TRACE) != 0 {
            unsafe { bindings::qemu_log(format_string.as_ptr() as *const c_char, _size /* as std::ffi::c_uint */, _id /* as std::ffi::c_int */, _addr /* as u64 */, _name.as_ptr(), _val /* as u64 */);}
        }
    }
}

